if (canvas.tokens.controlled.length === 0) {
  ui.notifications.warn("Please select at least one token first!");
} else {
  for (let token of canvas.tokens.controlled) {
    const currentDim = token.document.light.dim;

    if (currentDim === 0) {
      await token.document.update({
        light: {
          bright: 5,
          dim: 30,
          angle: 360,
          color: "#b0c4de",
          alpha: 0.35,
          animation: {
            type: "pulse",
            speed: 2,
            intensity: 2
          }
        }
      });
      ui.notifications.info(`Activated moonlight for ${token.name}`);
    }
    else {
      await token.document.update({
        light: {
          bright: 0,
          dim: 0,
          angle: 360,
          color: null,
          alpha: 0.5,
          animation: {
            type: null,
            speed: null,
            intensity: null
          }
        }
      });
      ui.notifications.info(`Deactivated moonlight for ${token.name}`);
    }
  }
}
